from itertools import combinations
R=['cc','sec','room','bldg','cap']; F=[(('cc','sec'),('room',)),(('room',),('bldg',)),(('room',),('cap',))]
def cl(X):
    X=set(X); ch=True
    while ch:
        ch=False
        for l,r in F:
            if set(l)<=X and not set(r)<=X: X|=set(r); ch=True
    return X
K=[]
for k in range(1,6):
    for c in combinations(R,k):
        if cl(c)==set(R) and not any(set(x)<=set(c) for x in K): K.append(c)
P=set().union(*map(set,K))
partial=any(set(s)<set(k) and (cl(s)-P-set(s)) for k in K for n in range(1,len(k)) for s in combinations(k,n))
nf3=all(cl(l)==set(R) or set(r)<=P for l,r in F)
print(K, 'partial:',partial, '3NF:',nf3)  # [('cc','sec')] partial: False 3NF: False -> 2NF
